contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address account) public {
        // The product is freshly deployed and has never been initialized:
        // the oracle is unset, so settling/fee logic cannot run and any
        // position-opening call must revert rather than corrupt state.
        require(true);

        bool reverted;
        try c.openTakeFor(account, UFixed18.wrap(amount)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted &&
            c.latestVersion() == 0 &&
            !c.closed()
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 maker, uint256 taker) public view {
        require(true);

        JumpRateUtilizationCurve memory curve = c.utilizationCurve();
        Fixed18 r = c.rate(Position(UFixed18.wrap(maker), UFixed18.wrap(taker)));

        // rate = compute(utilization) / (365 days), so per-second rate must lie
        // between minRate/(BASE*365days) and maxRate/(BASE*365days).
        uint256 denom = 1e18 * 365 days;
        assert(
            Fixed18.unwrap(r) >= Fixed18.unwrap(curve.minRate) / denom &&
            Fixed18.unwrap(r) <= Fixed18.unwrap(curve.maxRate) / denom
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 maker, uint256 taker) public view {
        require(true);

        JumpRateUtilizationCurve memory curve = c.utilizationCurve();
        Fixed18 r = c.rate(Position(UFixed18.wrap(maker), UFixed18.wrap(taker)));

        // rate = compute(utilization) / (365 days); per-second rate must lie
        // between minRate/(BASE*365days) and maxRate/(BASE*365days).
        int256 denom = int256(1e18 * 365 days);
        int256 lo = int256(PackedFixed18.unwrap(curve.minRate)) / denom;
        int256 hi = int256(PackedFixed18.unwrap(curve.maxRate)) / denom;
        int256 rv = Fixed18.unwrap(r);
        assert(rv >= lo && rv <= hi);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 maker, uint256 taker) public {
        require(maker > 0);

        JumpRateUtilizationCurve memory curve;
        bool okCurve;
        try c.utilizationCurve() returns (JumpRateUtilizationCurve memory cv) {
            curve = cv;
            okCurve = true;
        } catch {
            okCurve = false;
        }

        Fixed18 r;
        bool okRate;
        try c.rate(Position(UFixed18.wrap(maker), UFixed18.wrap(taker))) returns (Fixed18 rv) {
            r = rv;
            okRate = true;
        } catch {
            okRate = false;
        }

        assert(!okRate || !okCurve || (Fixed18.unwrap(r) >= int256(PackedFixed18.unwrap(curve.minRate)) / int256(1e18 * 365 days)
            && Fixed18.unwrap(r) <= int256(PackedFixed18.unwrap(curve.maxRate)) / int256(1e18 * 365 days)));
    }

    receive() external payable {}
}

