contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 newMaintenanceRaw) public {
        require(true);
        UFixed18 newMaintenance = UFixed18.wrap(newMaintenanceRaw);

        // The product was just deployed and never initialized, so this contract
        // (its controller address, since it created c) is not a registered
        // coordinator owner; ownership is enforced by updateMaintenance's
        // onlyProductOwner modifier for ANY input value.
        bool reverted;
        try c.updateMaintenance(newMaintenance) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: a non-owner can never change maintenance, regardless
        // of the value proposed.
        assert(reverted == true);
    }

    receive() external payable {}
}

