contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 maker, uint256 ratio) public {
        // maker must be a whole multiple of 1e18 so that utilization = ratio*1e18 is exact
        require(maker >= 1e18 && maker <= 1e30);
        require(maker % 1e18 == 0);
        require(ratio >= 1 && ratio <= 100);

        uint256 taker = maker * ratio;

        Position memory p1 = Position(UFixed18.wrap(maker), UFixed18.wrap(taker));
        Position memory p2 = Position(UFixed18.wrap(maker * 2), UFixed18.wrap(taker * 2));

        Fixed18 r1 = c.rate(p1);
        Fixed18 r2 = c.rate(p2);

        // Both positions have the exact same utilization (ratio * 1e18), so the
        // annualized rate must be identical: rate is invariant to position scale.
        assert(Fixed18.unwrap(r1) == Fixed18.unwrap(r2));
    }

    receive() external payable {}
}

