contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256 bigFee, uint256 smallFee) public {
        require(smallFee <= 1e18, "smallFee must be <= ONE");

        IProduct.ProductInfo memory info;
        info.name = "t";
        info.symbol = "T";
        info.payoffDefinition.payoffType = PayoffDefinitionLib.PayoffType.Linear;
        info.payoffDefinition.payoffDirection = PayoffDefinitionLib.PayoffDirection.Long;
        info.payoffDefinition.data = bytes30(0);
        info.oracle = IOracleProvider(address(this));
        info.maintenance = UFixed18.wrap(0);
        info.fundingFee = UFixed18.wrap(0);
        info.makerFee = UFixed18.wrap(0);
        info.takerFee = UFixed18.wrap(0);
        info.positionFee = UFixed18.wrap(0);
        info.makerLimit = UFixed18.wrap(0);
        c.initialize(info);

        bool r1;
        try c.updateFundingFee(UFixed18.wrap(bigFee)) { r1 = false; } catch { r1 = true; }

        bool r2;
        try c.updateFundingFee(UFixed18.wrap(smallFee)) { r2 = false; } catch { r2 = true; }

        assert((bigFee <= 1e18 || r1) && (!r2) && UFixed18.unwrap(c.fundingFee()) == smallFee);
    }

    fallback(bytes calldata input) external returns (bytes memory) {
        bytes4 sel = bytes4(input);
        if (sel == IOracleProvider.currentVersion.selector ||
            sel == IOracleProvider.sync.selector ||
            sel == IOracleProvider.atVersion.selector) {
            return abi.encode(uint256(0), uint256(0), int256(0));
        }
        if (sel == IController.coordinatorFor.selector) {
            return abi.encode(uint256(1));
        }
        if (sel == IController.owner(uint256).selector) {
            return abi.encode(address(this));
        }
        if (sel == IController.isProduct.selector) {
            return abi.encode(true);
        }
        if (sel == IController.paused.selector) {
            return abi.encode(false);
        }
        if (sel == IController.incentivizer.selector || sel == IController.collateral.selector) {
            return abi.encode(address(this));
        }
        revert("mock: unknown selector");
    }

    receive() external payable {}
}

